import React, { useEffect, useState } from "react";
import { useNavigate } from "react-router-dom";

function LevelsPage() {
  const [problem, setProblem] = useState([]);
  const [completedLevels, setCompletedLevels] = useState([]);
  const navigate = useNavigate();

  useEffect(() => {
    fetch("http://localhost:5000/problem")
      .then(res => res.json())
      .then(data => setProblem(data));
  }, []);

  const isUnlocked = (level) => {
    if (level === 1) return true;
    return completedLevels.includes(level - 1);
  };

  const startLevel = (level) => {
    navigate(`/manaco-editor/${level}`);
  };

  return (
    <div style={{ backgroundColor: "black", color: "yellow", minHeight: "100vh" }}>
      <h1>Problem Table</h1>

      <table border="3" cellPadding="10">
        <thead>
          <tr>
            <th>ID</th>
            <th>Level</th>
            <th>Title</th>
            <th>Description</th>
            <th>Action</th>
          </tr>
        </thead>

        <tbody>
          {problem.map((p) => {
            const unlocked = isUnlocked(p.level);
            const completed = completedLevels.includes(p.level);

            return (
              <tr
                key={p.id}
                style={{
                  backgroundColor: completed ? "green" : "transparent",
                  opacity: unlocked ? 1 : 0.4
                }}
              >
                <td>{p.id}</td>
                <td>Level {p.level}</td>
                <td>{p.title}</td>
                <td>{p.description}</td>
                <td>
                  <button
                    disabled={!unlocked}
                    onClick={() => startLevel(p.level)}
                  >
                    {completed ? "Completed ✅" : unlocked ? "Start" : "Locked 🔒"}
                  </button>
                </td>
              </tr>
            );
          })}
        </tbody>
      </table>
    </div>
  );
}

export default LevelsPage;
